let connectionError=null,reconnecting=false;
const connectionMessage='服务器未连接，请点击重新连接。';
async function requestJson(path,data){
  try{return await globalThis.KanpaceHttp.requestJson(path,data);}
  catch(error){if(error.code==='NETWORK_UNAVAILABLE'&&error.status!==401)showConnectionNotice(error);throw error;}
}
async function api(path,data){const {response,result}=await requestJson(path,data);if(!response.ok){const error=new Error((result.error||'操作失败')+(result.details?'\n'+(Array.isArray(result.details)?result.details.join('\n'):JSON.stringify(result.details)):''));error.status=response.status;error.details=result.details;throw error;}return result;}
function connectionBanner(error){const box=document.createElement('div');box.className='error-banner connection-banner';box.setAttribute('role','alert');box.textContent=error.message;const b=document.createElement('button');b.className='btn';b.textContent='重新连接';b.dataset.action='reconnect';box.append(b);return box;}
