function clearConnectionNotice(){connectionError=null;for(const box of document.querySelectorAll('.connection-banner'))box.remove();const error=$('#modal .dialog-error');if(error?.textContent===connectionMessage)error.textContent='';const notice=$('#toast');if(notice?.textContent===connectionMessage)notice.classList.remove('show');}
