async function readWorkspaceState(){const token=++refreshToken;if(typeof ensureAccessState==='function')await ensureAccessState();const [fresh,workspaceContext]=await Promise.all([api('/api/state'),api('/api/workspace')]);if(typeof ensureAccessState==='function'){await ensureAccessState();page=accessGuardPage(page);}if(token!==refreshToken)return;state=fresh;window.kanpaceInstanceContext=workspaceContext;if(!location.hash)page=accessGuardPage(['worker','quality'].includes(accessState?.user?.role)?'tasks':'workflow');if(workspaceContext.isolated)workspacePersist(workspaceContext.instance.factory_type);for(const tr of [...(state.people||[]).flatMap(p=>p.skills||[]),...(state.tasks||[]).map(t=>t.trade)].filter(Boolean))if(!trades.includes(tr))trades.push(tr);if(typeof operationsReset==='function')operationsReset();if(typeof operationsReadinessReset==='function')operationsReadinessReset();if(typeof operationsSchedulingReset==='function')operationsSchedulingReset();if(typeof operationsExchangeReset==='function')operationsExchangeReset();if(typeof operationsCalibrationKey!=='undefined')operationsCalibrationKey='';syncWorkspaceProject();const p=currentProject();projectId=p?.id||'';if(projectId)try{localStorage.setItem('kanpace-project-'+workspaceType,projectId)}catch{};if(page==='quote'||tab==='quote'){const freshQuote=p?await api(`/api/projects/${p.id}/quote`):null;if(token!==refreshToken)return;quote=freshQuote;}if(token!==refreshToken)return;if(page==='planning'&&typeof planningReset==='function'){planningKey='';if(typeof referenceKey!=='undefined')referenceKey='';}render();lastStateRefreshAt=Date.now();clearConnectionNotice();if(pendingTaskDeepLink&&!$('#modal').open){const id=pendingTaskDeepLink;pendingTaskDeepLink='';await taskModal(id);}}
// Returning to the browser must not replace controls beneath the user's first click.
function canRefreshOnFocus(){return kanpaceAppStarted&&!!state&&!document.hidden&&!uploadBusy&&!document.querySelector('dialog[open]')&&!document.activeElement?.closest('input,textarea,select,[contenteditable="true"]');}
