function showError(e){if(e.status===401&&typeof accessRequireLogin==='function'){accessRequireLogin();return;}if(e.code==='NETWORK_UNAVAILABLE'){showConnectionNotice(e);toast(e.message);return;}if(!state){$('#app').innerHTML=`<main id="main" class="boot"><h1>暂时无法读取项目</h1><p style="margin:16px 0">${esc(e.message)}</p>${button('重新连接','reconnect','refresh','primary')}</main>`;return;}toast(e.message);const main=$('#main');if(main){main.querySelector('.error-banner:not(.connection-banner)')?.remove();const box=document.createElement('div');box.className='error-banner';box.setAttribute('role','alert');box.textContent=e.message;if(e.code==='INVALID_RESPONSE'){const b=document.createElement('button');b.className='btn';b.textContent='重新连接';b.dataset.action='reconnect';box.append(b);}main.prepend(box);}}
