function projectWorkflowContext(project, profileOverride = undefined) {
  const context = globalThis.kanpaceInstanceContext;
  const candidate = profileOverride === undefined ? context?.profile : profileOverride;
  const profile = project?.factory_id && candidate?.status === 'installed' &&
    candidate.factory_id === project.factory_id && candidate.factory_type === (project.factory_type || 'cabinet') &&
    (!project.industry_id || candidate.industry_id === project.industry_id) ? candidate : null;
  const instance = project?.factory_id && context?.instance?.factory_id === project.factory_id ? context.instance : null;
  const industryId = project?.industry_id || profile?.industry_id || instance?.industry_id || '';
  const industryName = project?.industry_name || profile?.industry_name || instance?.industry_name || '';
  return {profile, industryId, industryName, sourceLabel:industryId ? '本行业工艺资料' : '工程资料',
    useWorkflow:Boolean(project?.workflow_id || industryId || profile || project?.factory_type && project.factory_type !== 'cabinet'),
    needsConfiguration:Boolean(industryId && !profile && !project?.workflow_id)};
}
