function projectDrawingToolbar(draft=false){
  const p=currentProject();if(!p||projectIsClosed(p))return '';
  const workflow=projectWorkflowContext(p),ps=parts(),ts=tasks(),pending=ps.filter(part=>part.review_status!=='approved').length;
  const canEdit=typeof accessCan!=='function'||accessCan('engineering');
  const agent=button('检查这单还缺什么','agent-open','search','',`data-agent-prompt="检查当前订单的拆单依据" data-agent-project="${esc(p.id)}"`);
  const recognize=typeof KanpaceIntelligence!=='undefined'||globalThis.KanpaceIntelligence?`<button class="btn ${!workflow.useWorkflow&&(!ps.length||draft)?'primary':''}" type="button" data-intel="engineering" ${canEdit?'':'disabled'}>${icon('layers')}识别图纸 / 核对模型</button>`:'';
  let next='',detail='从施工图、拆件图或模型提取依据，核对后形成任务。';
  if(workflow.useWorkflow){detail='按本厂流程核对工作对象、工艺依据和工序。';next=button(workflow.needsConfiguration?'查看本厂流程':'核对项目工作包','ops-go-templates','arrow','primary');}
  else if(draft){const questions=ps.reduce((n,part)=>n+(part.review_questions?.length||0),0)+(p.order_draft?.issues?.length||0);detail=questions?`${questions} 项信息待核对，按原图确认后再形成生产任务。`:'按柜号核对图纸、构件和各工种工作范围。';next=button(questions?`核对 ${questions} 项疑问`:'查看任务草稿','tab','arrow','',`data-tab="${questions?'draft-review':'tasks'}"`);}
  else if(pending){detail=`${pending} 项构件待核对尺寸、材料和数量。`;next=button('继续构件复核','review-next','arrow','primary',canEdit?'':'disabled');}
  else if(ps.length){const stale=ts.filter(t=>t.status==='invalidated'||t.revision!==p.revision);detail=stale.length?`当前工程 R${p.revision}，${stale.length} 道旧任务待重审，不能派工。`:'构件已复核，继续核对各工种工序与生产依据。';next=button(ts.length?(p.status==='released'&&p.released_revision===p.revision?'查看生产任务':'核对任务草稿'):'生成任务草稿',ts.length?'open-tasks':'generate','arrow','primary',canEdit?'':'disabled');}
  return `<section class="factory-drawing-tools" aria-label="拆单操作"><div><h2>${workflow.useWorkflow?'本厂流程拆解':'AI 辅助拆单'}</h2><p>${esc(detail)}</p></div><div class="factory-drawing-tool-actions">${recognize}${next}${agent}</div></section>`;
}
function stageStrip(){const ps=parts(), ts=tasks(),p=currentProject();let cur=!ps.length?0:ps.some(p=>p.review_status!=='approved')?1:p?.status!=='released'?2:3;const data=[['导入工程资料',`${docs().length} 个来源文件`],['构件与工艺复核',`${ps.filter(p=>p.review_status==='approved').length} / ${ps.length} 项已确认`],['生成任务草稿',`${ts.length} 道工序`],['派工与生产',`${ts.filter(t=>t.status==='done').length} 道已完成`]];return `<div class="stages">${data.map(([n,d],i)=>`<div class="stage ${i<cur?'done':i===cur?'current':''}"><span class="stage-num">${i<cur?icon('check'):String(i+1).padStart(2,'0')}</span><div><h3>${n}</h3><p>${d}</p></div></div>`).join('')}</div>`;}
function tabs(){return `<div class="project-tabs" role="tablist" aria-label="项目工作区">${[['parts','layers',projectWorkflowContext(currentProject()).industryId?'工艺资料':'图纸与构件'],['tasks','tasks',currentProject()?.status==='released'&&currentProject()?.released_revision===currentProject()?.revision?'生产任务':'任务草稿'],['history','history','版本记录']].map(([t,i,n])=>`<button role="tab" aria-selected="${tab===t}" class="tab ${tab===t?'active':''}" data-action="tab" data-tab="${t}">${icon(i)}${n}${t==='parts'?`<span class="mono">${projectWorkflowContext(currentProject()).industryId?docs().filter(d=>!d.superseded&&d.purpose!=='render'&&d.purpose!=='reference').length:parts().length}</span>`:''}</button>`).join('')}</div>`;}
function demoDrawing(){return `<svg class="plan" viewBox="0 0 720 365" role="img" aria-label="综合展示柜构件关系示意，非原始CAD几何"><defs><marker id="arr" viewBox="0 0 6 6" refX="3" refY="3" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0 6 3 0 6" fill="none" stroke="#95a2b3"/></marker></defs><g transform="translate(${360*(1-zoom)} ${182*(1-zoom)}) scale(${zoom})"><g stroke-linejoin="round"><path d="m197 240 216 47 151-66-210-42Z" fill="#e7ebf0" opacity=".5"/><path d="m186 225 225 48 141-61v-74L329 94 186 153Z" fill="#f3eee7" stroke="#a39a8c" stroke-width="1.3"/><path d="m186 225 225 48v-76l-225-45Z" fill="#e7dfd2" stroke="#a99f8e"/><path d="m411 197 141-59v74l-141 61Z" fill="#d8cbb9" stroke="#a99f8e"/><path d="m197 216 202 43v-53l-202-40Z" fill="#f3eee6" stroke="#beb2a1"/><path d="m211 177 1 53m68-41v56m55-43v53" fill="none" stroke="#b4a794"/><path d="m421 201 118-50v48l-118 50Z" fill="#e8dece" stroke="#b4a794"/><path d="m190 145 221 45 139-59-221-42Z" fill="#fffaf1" stroke="#ad9c7e" stroke-width="1.2"/><path d="m190 71 221 44 139-58-221-39Z" fill="#def0f5" opacity=".44" stroke="#6fa0b4"/><path d="m190 71 221 44v75l-221-45Z" fill="#e8f4f9" fill-opacity=".4" stroke="#82a8b9"/><path d="m411 115 139-58v74l-139 59Z" fill="#d2eaf4" fill-opacity=".44" stroke="#7ca4b7"/><path d="M190 71v76m221-32v77M550 57v75M329 18v72" stroke="#92816a" stroke-width="3"/><path d="m190 71 221 44 139-58-221-39-139 53Zm0 75 221 45 139-60M329 90l221 41" fill="none" stroke="#a79b86" stroke-width="2"/><path d="m199 139 210 43 132-56" fill="none" stroke="#dfb45f" stroke-width="3"/><path d="m217 131 143 28 72-30-141-26Z" fill="#f1eadc" stroke="#c5b79a"/><path d="m253 124 23 5 16-7-22-4Z m63 13 23 5 16-7-22-4Z" fill="#c5b79a"/><path d="M200 230v12m199 26v13m141-66v12" stroke="#9c9487" stroke-width="5"/><path d="m217 95 140 29m-113-19 76 16m107 7 84-36" stroke="#fff" stroke-width="2" opacity=".85"/></g><g stroke="#9aa7b8" fill="none" stroke-width=".8"><path d="M173 236v31m238 16v32m-238-60 238 48" marker-start="url(#arr)" marker-end="url(#arr)"/><path d="m427 314 140-60m-11-25 19 31" marker-start="url(#arr)" marker-end="url(#arr)"/><path d="M568 57h37m-42 155h42m-12-155v155" marker-start="url(#arr)" marker-end="url(#arr)"/><path d="m265 69-75-30h-61M268 208l-89 38h-57M483 160h117"/></g><g fill="#758498" font-size="10" font-family="monospace"><text x="280" y="292" transform="rotate(11 280 292)">柜体 / 木作</text><text x="486" y="288" transform="rotate(-23 486 288)">五金框架</text><text x="610" y="142" transform="rotate(-90 610 142)">工艺分层示意</text><text x="91" y="35">01 玻璃罩</text><text x="78" y="250">02 木作基座</text><text x="607" y="164">03 灯带</text></g><g fill="#315ee8"><circle cx="265" cy="69" r="3"/><circle cx="268" cy="208" r="3"/><circle cx="483" cy="160" r="3"/></g></g></svg>`;}
function geometryDrawing(document){const gs=document?.geometry||[];const coords=[];for(const g of gs){for(const p of g.points||[])coords.push(p);if(g.x!=null&&g.y!=null){coords.push([g.x-(g.radius||0),g.y-(g.radius||0)],[g.x+(g.radius||0),g.y+(g.radius||0)])}}if(!coords.length)return null;let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;for(const point of coords){minX=Math.min(minX,point[0]);maxX=Math.max(maxX,point[0]);minY=Math.min(minY,point[1]);maxY=Math.max(maxY,point[1]);}const scale=Math.min(530/Math.max(maxX-minX,1),250/Math.max(maxY-minY,1))*zoom;const X=x=>360+(x-(minX+maxX)/2)*scale,Y=y=>182-(y-(minY+maxY)/2)*scale;const colours=['#557c9a','#9e855e','#315ee8','#769684'];return `<svg class="plan" viewBox="0 0 720 365" role="img" aria-label="DXF实体几何预览">${gs.map((g,i)=>{const c=colours[i%4];if(g.points?.length){const pts=g.points.map(p=>`${X(p[0])},${Y(p[1])}`).join(' ');return `<${g.closed?'polygon':'polyline'} points="${pts}" fill="${g.closed?c+'12':'none'}" stroke="${c}" stroke-width="1.3"><title>${esc(g.layer)} · ${esc(g.handle)}</title></${g.closed?'polygon':'polyline'}>`}if(g.type==='circle')return `<circle cx="${X(g.x)}" cy="${Y(g.y)}" r="${g.radius*scale}" fill="none" stroke="${c}"/>`;if(g.type==='text')return `<text x="${X(g.x)}" y="${Y(g.y)}" fill="#52677d" font-size="10">${esc(g.text)}</text>`;return ''}).join('')}</svg>`;}
function partDrawing(){const ps=parts().filter(p=>p.length&&p.width).slice(0,6);if(!ps.length)return `<div class="empty" style="padding-top:105px">${icon('file')}<h3>等待工程资料</h3><p>导入 DXF 查看实体，或导入 BOM 查看构件尺寸</p></div>`;return `<svg class="plan" viewBox="0 0 720 365" role="img" aria-label="依据BOM尺寸绘制的构件示意">${ps.map((p,i)=>{let x=80+(i%3)*210,y=72+Math.floor(i/3)*135,s=Math.min(160/p.length,85/p.width),w=p.length*s,h=p.width*s;return `<g transform="translate(${x} ${y})"><rect width="${w}" height="${h}" fill="${p.category==='glass'?'#e3f0f7':'#eee6d9'}" stroke="${p.category==='glass'?'#83a9bc':'#b5a28b'}"/><text x="0" y="${h+20}" fill="#5a6d80" font-size="10">${esc(p.name.slice(0,12))}</text><text x="0" y="${h+35}" fill="#788695" font-family="monospace" font-size="9">${p.length} × ${p.width} × ${p.thickness??'?'} mm</text></g>`}).join('')}</svg>`;}
function drawingPanel(requestedDocumentId=''){const ds=docs();const d=requestedDocumentId?ds.find(d=>d.id===requestedDocumentId):ds.find(d=>d.id===docId)||ds.filter(d=>!d.superseded&&!d.demo).slice(-1)[0]||ds.find(d=>d.geometry?.length)||ds[0];if(d&&!requestedDocumentId)docId=d.id;const geometry=geometryDrawing(d);if(d&&uploadDocIsPdf(d))return `<section class="panel uploaded-main-drawing"><div class="panel-head"><h2>${icon('file')}<span>${esc(d.filename)}</span></h2>${button('放大图纸','preview-upload','expand','',`data-id="${esc(d.id)}"`)}</div><button class="uploaded-main-preview" data-action="preview-upload" data-id="${esc(d.id)}" aria-label="查看${esc(d.filename)}"><img src="${esc(uploadPreviewSrc(d))}" alt="${esc(d.filename)} 第 1 页"></button><div class="drawing-footer"><span>${esc(uploadDocSummary(d))}</span><button class="link-button" data-action="documents">${ds.length} 个来源文件</button></div></section>`;if(d&&!d.demo&&!geometry&&d.part_count===0)return `<section class="panel"><div class="panel-head"><h2>${icon('file')}${esc(d.filename)}</h2></div><div class="empty">${icon('file')}<h3>${esc(uploadDocSummary(d))}</h3><p>${esc(d.warnings?.[0]||'请补充 PDF 图纸或 BOM 清单。')}</p><a class="btn" href="/api/documents/${encodeURIComponent(d.id)}/download" download>下载原文件</a>${uploadModelLink(d)}</div></section>`;return `<section class="panel"><div class="panel-head"><h2>${icon('file')}<span>${esc(d?.filename||'构件关系视图')}</span></h2><button class="link-button" data-action="documents">${ds.length} 个来源 ${icon('down')}</button></div><div class="drawing"><div class="drawing-label">${icon('cube')}${geometry?'DXF 实体 · 保留原始句柄':currentProject()?.demo?'演示构件关系 · 非 CAD 解析几何':'BOM 尺寸示意 · 非装配图'}</div>${geometry||(currentProject()?.demo?demoDrawing():partDrawing())}<div class="draw-caption">${geometry?'SOURCE GEOMETRY / DXF':'ENGINEERING WORKSPACE / REFERENCE'}</div><div class="draw-tools"><button data-action="zoom-out" aria-label="缩小图纸">${icon('minus')}</button><button data-action="zoom-reset" aria-label="重置图纸比例">${icon('expand')}</button><button data-action="zoom-in" aria-label="放大图纸">${icon('plus')}</button></div></div><div class="drawing-footer"><div class="legend"><span style="color:#9e855e"><i class="swatch"></i>木作 / 五金</span><span style="color:#6d99ad"><i class="swatch"></i>玻璃</span><span style="color:#b68f43"><i class="swatch"></i>灯光</span></div><span>${geometry&&!(d.geometry||[]).every(g=>g.units==='mm')?'图纸单位未确认':'单位 mm'} · 工程 R${currentProject()?.revision||1}</span></div></section>`;}
function partEvidencePreview(part){
  const entries=typeof draftMediaEntries==='function'?draftMediaEntries(part):[];
  const preferred=entries.findIndex(entry=>['工程图','施工图','来源料单'].includes(entry.kind));
  const index=preferred<0?0:preferred;
  const entry=entries[index];
  if(!entry){
    const status=draftMediaCache.get(currentProject()?.id)?.status;
    return '<span class="part-evidence-missing">'+(status==='loading'?'正在加载…':'待关联图纸')+'</span>';
  }
  const url=draftMediaURL(entry.thumb_url||entry.url);
  return '<button class="part-evidence-preview" data-action="draft-media-open" data-part="'+esc(part.id)+'" data-index="'+index+'" aria-label="放大查看'+esc(part.name)+'的'+esc(draftMediaLabel(entry))+'"><img src="'+esc(url)+'" alt="" loading="lazy" decoding="async"><span>'+esc(draftMediaLabel(entry))+'</span></button>';
}
function partsTable(){
  const ps=parts();
  if(typeof ensureDraftMedia==='function')ensureDraftMedia(currentProject());
  const rows=ps.map((p,i)=>'<tr class="part-row '+(p.id===selectedPart?'selected':'')+'"><td><button class="link-button part-name" style="color:inherit;text-align:left" data-action="part" data-id="'+esc(p.id)+'"><span class="part-code">'+String(i+1).padStart(2,'0')+'</span><span><strong>'+esc(p.name)+'</strong><small>'+esc(p.source?.part_number||p.source?.reference||p.category||'手动录入')+'</small></span></button></td><td class="part-evidence-cell">'+partEvidencePreview(p)+'</td><td><span class="part-material">'+esc(p.material||'材料待补充')+'</span><br><span class="mono muted part-dimensions">'+num(p.length??p.length_mm)+' × '+num(p.width??p.width_mm)+' × '+num(p.thickness??p.thickness_mm)+'</span></td><td class="mono">'+num(p.quantity)+' <span class="muted small">件</span></td><td>'+tag(p.review_status||'pending')+'</td><td><button class="link-button" data-action="part" data-id="'+esc(p.id)+'" aria-label="复核'+esc(p.name)+'">'+icon('chevron')+'</button></td></tr>').join('');
  return '<section class="panel section-gap"><div class="panel-head"><h2>构件清单 <span class="badge">'+ps.length+' 项</span></h2><button class="link-button" data-action="add-part">'+icon('plus')+' 手动添加</button></div>'+(!ps.length?empty('还没有构件','从图纸或 BOM 开始建立这张订单的生产依据'):'<div class="table-wrap"><table><thead><tr><th>构件 / 来源</th><th>图纸依据</th><th>材质与规格</th><th>数量</th><th>复核状态</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="table-actions">尺寸、材料与数量需技术员确认'+button('逐项复核','review-next','arrow')+'</div>')+'</section>';
}
function reviewPanel(){const workflowContext=projectWorkflowContext(currentProject());const workflowNodes=tasks().filter(t=>t.status!=='invalidated'&&t.revision===currentProject()?.revision);const routeRows=workflowNodes.length?workflowNodes:workflowContext.profile?.nodes||[];const routeTrades=[...new Set(routeRows.map(n=>n.trade||n.role).filter(Boolean))];if(workflowContext.useWorkflow)return `<div class="right-column"><section class="panel"><div class="panel-head"><h2>${workflowContext.needsConfiguration?'本厂流程待配置':'工作包复核'}</h2></div><div class="planning-empty compact"><p>${esc(workflowContext.needsConfiguration?'已选择行业，请联系管理员在中台核对并启用本厂流程。':workflowContext.industryName?workflowContext.industryName+' · 按工作对象核对工艺资料、数量和工序。':'按本厂流程核对工作对象、资料和工序。')}</p>${button(workflowContext.needsConfiguration?'查看本厂流程':'打开项目工作包','ops-go-templates','layers','primary')}</div></section>${routeTrades.length?`<section class="panel section-gap"><div class="panel-head"><h2>本厂工序</h2><small>${routeRows.length} 道</small></div><div class="route-list">${routeTrades.slice(0,6).map(trade=>`<div class="route-item"><div><strong>${esc(trade)}</strong><small>${routeRows.filter(n=>(n.trade||n.role)===trade).slice(0,2).map(n=>esc(n.name||n.title)).join(' · ')}</small></div><span class="route-count">${routeRows.filter(n=>(n.trade||n.role)===trade).length} 道</span></div>`).join('')}</div></section>`:''}</div>`;const ps=parts(),ok=ps.filter(p=>p.review_status==='approved').length,pending=ps.length-ok,issues=ps.filter(p=>p.issues?.length),unresolved=docs().filter(d=>(['needs_conversion','error'].includes(d.status)||d.part_count===0)&&!d.resolved&&!d.superseded),ts=tasks();return `<div class="right-column"><section class="panel"><div class="panel-head"><h2>${icon('checkcircle')}拆单复核</h2></div><div class="review-content"><div class="review-title"><div class="review-icon">${icon('layers')}</div><div><h3>构件确认进度</h3></div><div class="review-number">${ok}<span style="font-size:12px;color:#8a95a4">/${ps.length}</span></div></div><div class="progress-track"><i style="width:${ps.length?ok/ps.length*100:0}%"></i></div><div class="review-summary"><span>${!ps.length?'尚未建立构件':pending?`${pending} 项等待技术复核`:'所有构件已复核'}</span><span>${ps.length?Math.round(ok/ps.length*100):0}%</span></div><div class="check-row">${icon('checkcircle')}<div><strong>工程依据留存</strong><small>${docs().length?docs().length+' 个来源文件 · 查看原件':currentProject()?.demo?'内置演示 BOM · 非真实图纸':'人工构件记录 · 尚未导入原图'}</small></div></div><div class="check-row ${issues.length||unresolved.length?'warn':''}">${icon(issues.length||unresolved.length?'alert':'checkcircle')}<div><strong>${issues.length||unresolved.length?'有信息需要补充':'构件完整性检查'}</strong><small>${issues.length} 项构件问题 · ${unresolved.length} 个待转换文件</small></div></div><div class="check-row ${!ps.length||pending?'warn':''}">${icon(!ps.length||pending?'clock':'checkcircle')}<div><strong>技术员确认</strong><small>${!ps.length?'添加构件后复核':pending?'请确认尺寸、材质、数量及做法':'可以生成工序'}</small></div></div>${pending?'<div class="callout">先完成构件复核，再发布工序。</div>':''}${button(pending?'继续构件复核':ts.length?(currentProject()?.status==='released'&&currentProject()?.released_revision===currentProject()?.revision?'查看生产任务':'核对任务草稿'):'生成任务草稿',pending?'review-next':ts.length?'open-tasks':'generate',pending?'arrow':'tasks','full',!ps.length?'disabled':'')}</div></section><section class="panel section-gap"><div class="panel-head"><h2>工艺覆盖</h2><small>按构件匹配</small></div><div class="route-list">${trades.filter(tr=>ts.some(t=>(t.trade||t.role)===tr)||['木工','五金','玻璃','电工'].includes(tr)).slice(0,6).map(tr=>`<div class="route-item"><span class="trade-icon">${icon(tradeIcons[tr])}</span><div><strong>${tr}</strong><small>${({'木工':'开料 → 封边 / 组坯','五金':'加工 → 焊接 / 表面处理','油漆':'基层 → 涂装 → 检查','玻璃':'尺寸核对 → 加工 / 验收','电工':'灯光安装 → 电气检查','装配':'齐套核对 → 总装','质检':'外观 · 尺寸 · 功能','包装':'保护 → 包装 → 标识'})[tr]}</small></div><span class="route-count">${ts.filter(t=>(t.trade||t.role)===tr).length} 道</span></div>`).join('')}</div></section></div>`;}
function historyOnlyView(){const project=currentProject();return `<div class="page-head version-page-head"><div><p>${esc(project?.name||'当前项目')} · R${esc(project?.revision||1)}</p><h1>图纸版本记录</h1></div><a class="btn" href="#page=drawing&tab=parts&project=${encodeURIComponent(project?.id||'')}">返回拆与核对</a></div>${historyView()}`;}
function drawingView(){if(!currentProject())return projectList();if(tab==='history')return historyOnlyView();if(currentProject().order_draft&&!projectWorkflowContext(currentProject()).useWorkflow)return orderDraftView();let body=tab==='parts'?`${projectDrawingToolbar()}${documentConfirmationsPanel()}<div class="workspace-grid factory-drawing-workspace"><div>${projectVisualPanel()}${projectEngineeringPanel()}${globalThis.KanpaceRound1?`<details class="drawing-optional"><summary>外形模型核对（可选）</summary>${globalThis.KanpaceRound1.panel(currentProject())}</details>`:''}${projectWorkflowContext(currentProject()).useWorkflow?'':partsTable()}</div>${reviewPanel()}</div>`:tab==='tasks'?taskView(true):tab==='quote'?quoteView(true):historyView();return projectHead()+tabs()+body;}
function documentConfirmationStages(){return [['render','效果图'],['construction','施工图'],['engineering','工程图']];}
function documentConfirmationEnabled(project=currentProject()){return !!project&&(project.factory_type||'cabinet')==='cabinet'&&!project.demo&&project.evidence_policy==='staged'&&!project.workflow_id;}
function documentConfirmationDocuments(stage,project=currentProject()){
  const formats={construction:/\.(dwg|dxf|pdf|png|jpg|jpeg|webp)$/i,engineering:/\.(sldasm|sldprt|slddrw|step|stp|iges|igs|brep|pdf|dxf|dwg)$/i};
  return (state?.documents||[]).filter(doc=>doc.project_id===project?.id&&typeof doc.id==='string'&&doc.id.startsWith('doc_')&&!doc.demo&&!doc.superseded&&!doc.archived&&doc.sha256&&(stage==='render'?doc.purpose==='render':(doc.purpose||'drawing')==='drawing'&&formats[stage]?.test(doc.filename||'')));
}
function documentConfirmationCurrent(stage,project=currentProject()){
  const record=project?.document_confirmations?.[stage];
  if(!record||typeof record!=='object')return null;
  const documentRecord=documentConfirmationDocuments(stage,project).find(doc=>doc.id===record.document_id&&doc.sha256===record.document_sha256);
  return documentRecord?{record,document:documentRecord}:null;
}
function documentConfirmationSourceParts(doc,project=currentProject()){
  return (state?.parts||[]).filter(part=>part.project_id===project?.id&&part.document_id===doc?.id&&!part.archived);
}
function documentConfirmationPartApproved(part){return !!part&&!part.archived&&!part.draft_only&&(part.review_status==='approved'||part.approved===true);}
function documentConfirmationReadyDoc(stage,doc,project=currentProject()){
  if(stage!=='engineering')return true;
  const construction=documentConfirmationCurrent('construction',project)?.document;
  if(!doc||doc.id===construction?.id)return false;
  if(doc.resolved){
    const evidence=doc.resolution_evidence,pins=evidence?.parts;
    if(evidence?.document_id!==doc.id||evidence?.document_sha256!==doc.sha256||evidence?.project_id!==project?.id||!Array.isArray(pins)||!pins.length)return false;
    return pins.every(pin=>{
      const part=(state?.parts||[]).find(item=>item.id===pin.part_id&&item.project_id===project.id&&!item.archived);
      const source=(state?.documents||[]).find(item=>item.id===pin.source_document_id&&item.project_id===project.id&&!item.superseded&&!item.archived);
      return !!source&&documentConfirmationPartApproved(part)&&part.document_id===source.id&&source.sha256===pin.source_sha256;
    });
  }
  const linked=documentConfirmationSourceParts(doc,project);
  return !!linked.length&&linked.every(documentConfirmationPartApproved);
}
function documentConfirmationEngineeringHint(candidates,project=currentProject()){
  const construction=documentConfirmationCurrent('construction',project)?.document;
  const distinct=candidates.filter(doc=>doc.id!==construction?.id);
  if(!distinct.length)return '工程图不能与施工图使用同一文件，请另上传工程图。';
  const pending=distinct.flatMap(doc=>documentConfirmationSourceParts(doc,project)).filter(part=>!documentConfirmationPartApproved(part));
  if(pending.length)return `先审核本文件的 ${pending.length} 项构件，再确认工程图。`;
  if(distinct.some(doc=>doc.resolved))return '工程图与构件的核验关联已失效，请重新核对来源。';
  return '先将工程图关联到当前构件或配套清单，并完成审核。';
}
function documentConfirmationsPanel(){
  const project=currentProject();if(!documentConfirmationEnabled(project))return '';
  const readOnly=projectIsClosed(project),canEdit=!readOnly&&(typeof accessCan!=='function'||accessCan('engineering'));
  const stages=documentConfirmationStages();
  return `<section class="panel document-confirmations" aria-labelledby="document-confirmations-title"><div class="document-confirmations-head"><div><h2 id="document-confirmations-title">客户确认</h2><p>按客户确认的文件逐项记录；换版后需重新确认。</p></div><span class="document-confirmations-count">${stages.filter((entry,index)=>stages.slice(0,index+1).every(([stage])=>documentConfirmationCurrent(stage,project))).length} / 3</span></div><ol class="document-confirmations-list">${stages.map(([stage,label],index)=>{
    const previous=stages.slice(0,index).every(([name])=>documentConfirmationCurrent(name,project));
    const current=previous?documentConfirmationCurrent(stage,project):null,old=project.document_confirmations?.[stage];
    const candidates=documentConfirmationDocuments(stage,project);
    const ready=candidates.some(doc=>documentConfirmationReadyDoc(stage,doc,project));
    const status=current?'已记录':!previous?'等上一步':old?'文件已换版':'待确认';
    const hint=current?`<span class="document-confirmations-file">${esc(current.document.filename)}</span>${current.record.note?`<small>依据：${esc(current.record.note)}</small>`:''}`:
      !previous?`先记录${esc(stages[index-1][1])}确认；可先上传本阶段文件。`:
      old?'原确认文件已失效，请选择当前文件重新记录。':
      stage==='engineering'&&!ready&&candidates.length?esc(documentConfirmationEngineeringHint(candidates,project)):
      candidates.length?`已上传 ${candidates.length} 个可选文件，选择客户确认的版本。`:'先上传客户确认的文件，可分批添加。';
    return `<li class="document-confirmation-item"><span class="document-confirmation-step" aria-hidden="true">${index+1}</span><div class="document-confirmation-main"><div class="document-confirmation-line"><strong>${esc(label)}</strong><span class="document-confirmation-state ${current?'is-done':previous&&old?'is-stale':''}">${status}</span></div><p>${hint}</p></div>${readOnly?'':`<div class="document-confirmation-actions">${button('上传','document-confirmation-upload','upload','',`data-stage="${stage}" ${canEdit?'':'disabled'}`)}${stage==='engineering'&&previous&&!ready&&candidates.length?button('核对来源','documents','file','',canEdit?'':'disabled'):button(current?'更换确认':'选择并确认','document-confirmation-open','check','',`data-stage="${stage}" ${canEdit&&previous&&ready?'':'disabled'}`)}</div>`}</li>`;
  }).join('')}</ol>${!readOnly?'<p class="document-confirmation-note">工程图确认前，先核对构件的材料、尺寸和数量。</p>':''}</section>`;
}
function documentConfirmationModal(stage){
  const project=currentProject(),stages=documentConfirmationStages(),index=stages.findIndex(([id])=>id===stage);
  if(!documentConfirmationEnabled(project)||index<0||projectIsClosed(project))return;
  if(typeof accessCan==='function'&&!accessCan('engineering'))return toast('当前账号没有工程确认权限');
  if(!stages.slice(0,index).every(([name])=>documentConfirmationCurrent(name,project)))return toast('请先记录上一阶段的客户确认');
  const label=stages[index][1],current=documentConfirmationCurrent(stage,project),candidates=documentConfirmationDocuments(stage,project);
  const ready=candidates.filter(doc=>documentConfirmationReadyDoc(stage,doc,project));
  if(!ready.length){
    const message=stage==='engineering'&&candidates.length?documentConfirmationEngineeringHint(candidates,project):'本项目暂无可确认的'+label+'文件。';
    openModal(label+'确认',`<p>${esc(message)}</p>`,button('关闭','close')+button('上传'+label,'document-confirmation-upload','upload','primary',`data-stage="${stage}"`));
    return;
  }
  const later=stages.slice(index+1).some(([name])=>project.document_confirmations?.[name]);
  openModal(label+'确认',`<form id="document-confirmation-form" method="post" action="/api/projects/${encodeURIComponent(project.id)}/document-confirmations" data-project-id="${esc(project.id)}" data-stage="${stage}" data-confirmation-version="${Number(project.document_confirmation_version)||0}"><label class="field" for="document-confirmation-file">客户确认的${label}<select id="document-confirmation-file" name="document_id" required><option value="">请选择本项目文件</option>${ready.map(doc=>`<option value="${esc(doc.id)}" ${current?.document.id===doc.id?'selected':''}>${esc(doc.filename)} · R${esc(doc.revision||'—')}</option>`).join('')}</select></label><label class="field" for="document-confirmation-note">确认依据（必填）<textarea id="document-confirmation-note" name="note" maxlength="500" required placeholder="例如：客户 9 月 28 日在微信确认了此版图纸">${esc(current?.record.note||'')}</textarea></label><p class="form-note">${stage==='engineering'?'工程图应对应已核对的构件、材料、尺寸和数量。':'系统会保存所选文件的当前版本作为确认依据。'}${later?' 重新确认本阶段会清除后续阶段的记录。':''}</p></form>`,button('取消','close')+button('记录客户确认','save-document-confirmation','check','primary','type="submit" form="document-confirmation-form"'));
}
async function saveDocumentConfirmation(form,submitButton){
  if(!form.reportValidity())return;
  const project=state.projects.find(item=>item.id===form.dataset.projectId),stage=form.dataset.stage;
  const selectedId=form.elements.document_id.value,doc=documentConfirmationDocuments(stage,project).find(item=>item.id===selectedId);
  const error=$('#modal .dialog-error');
  if(!project||currentProject()?.id!==project.id||!documentConfirmationEnabled(project)||projectIsClosed(project)||!doc||!documentConfirmationReadyDoc(stage,doc,project)){
    if(error)error.textContent='项目或文件已变化，请关闭弹窗刷新后重新选择。';
    form.elements.document_id.focus();return;
  }
  const note=form.elements.note.value.trim();
  if(!note){if(error)error.textContent='请写明客户确认依据。';form.elements.note.focus();return;}
  if(error)error.textContent='';
  await submitOperation(submitButton,()=>api(`/api/projects/${encodeURIComponent(project.id)}/document-confirmations`,{
    stage,document_id:doc.id,document_sha256:doc.sha256,note,expected_confirmation_version:Number(form.dataset.confirmationVersion)
  }),stagesLabel(stage)+'确认已记录');
}
function stagesLabel(stage){return documentConfirmationStages().find(([id])=>id===stage)?.[1]||'图纸';}
