async function executionSave(buttonEl,operation){
  const form=$('#task-execution-form');if(taskProjectIsClosed(executionTask(form?.dataset.id)))throw new Error('项目已归档，重新打开后可报工');if(!form?.reportValidity())return;const v=formValues('#task-execution-form'),id=form.dataset.id,t=executionTask(id);
  let data={expected_execution_version:Number(form.dataset.version)},targetId='';
  if(operation==='progress'){data.completed_quantity=Number(v.completed_quantity);data.note=v.note;}
  if(operation==='pause'||operation==='switch'){data.reason=v.reason;data.note=v.note;data.handover_note=v.handover_note;if(v.completed_quantity!=='')data.completed_quantity=Number(v.completed_quantity);}
  if(operation==='resume'){data.note=v.note;data.handover_note=v.handover_note;}
  if(operation==='priority'){data.priority=Number(v.priority);data.reason=v.reason;}
  if(operation==='switch'){targetId=v.target_task_id;const target=executionQueueById.get(targetId);if(!target||!target.can_switch)throw new Error('请先选择允许切换的任务');data.target_task_id=targetId;data.target_expected_execution_version=Number($('#switch-target-version').value);if(target.status==='blocked')data.target_note=v.target_note;}
  if(operation==='complete'){data.status='done';data.note=v.note;if(executionQuantity(t)!=null)data.completed_quantity=t.quantity;operation='status';}
  const controls=Array.from($('#modal').querySelectorAll('button')).map(b=>({button:b,disabled:b.disabled}));controls.forEach(({button})=>button.disabled=true);let saved=false;
  try{await executionRequest(`/api/tasks/${encodeURIComponent(id)}/${operation}`,data);saved=true;const next=targetId||id;executionNotice={id:next,text:targetId?'已换到 '+(executionTask(targetId)?.title||'目标任务'):operation==='pause'?'任务已暂停':operation==='resume'?'任务已恢复':operation==='progress'?'进度已保存':operation==='priority'?'优先级已调整':'工序已完工'};await refresh();await taskModal(next);toast(executionNotice.text);}
  catch(e){const error=$('#modal .dialog-error');error.replaceChildren(document.createTextNode(saved?'业务状态已保存，但最新视图读取失败，请重新载入核对。'+e.message:e.message));if(e.status===409||saved){const p=document.createElement('p');p.textContent=saved?'保存成功，请重新载入查看。':'任务已变化，请重新载入后核对。';error.append(p);const b=document.createElement('button');b.className='btn';b.dataset.action='task-exec-reload';b.dataset.id=id;b.textContent='重新载入任务';error.append(b);}}
  finally{controls.filter(x=>x.button.isConnected).forEach(({button,disabled})=>button.disabled=saved||disabled);}
}
function executionSwitchPreview(){const select=$('#switch-target');if(!select)return;const t=executionQueueById.get(select.value),box=$('#switch-target-preview'),resolution=$('#switch-resolution'),input=$('#switch-target-version');if(!t){box.innerHTML='<p>选择同一负责人的另一项工序，查看前置条件。</p>';resolution.hidden=true;$('textarea',resolution).required=false;input.value='';return;}input.value=executionVersion(t);const p=state.projects.find(p=>p.id===t.project_id);box.innerHTML=`<strong>${esc(p?.name||'项目')} · ${executionPriorityNames[executionPriority(t)]}</strong><p>${esc(t.title||t.name)}</p>${executionProgress(t)}${executionHandover(t)}${t.switch_blockers?.length?`<div class="execution-blockers">${t.switch_blockers.map(s=>`<p>${esc(s)}</p>`).join('')}</div>`:'<p>可以切换</p>'}`;resolution.hidden=t.status!=='blocked';$('textarea',resolution).required=t.status==='blocked';}
async function executionAction(a,b){
  const id=b.dataset.id,t=executionTask(id);if(a==='task-exec-back')return taskModal(id);if(a==='task-exec-reload'){await refresh();return taskModal(id);}if(a==='task-exec-save')return executionSave(b,b.dataset.operation);if(!t)return;if(taskProjectIsClosed(t))throw new Error('项目已归档，重新打开后可操作');
  const note=$('#task-form textarea[name="note"]')?.value||'';
  if(a==='task-exec-start'){const version=Number($('#task-form')?.dataset.version??executionVersion(t));return submitOperation(b,()=>executionRequest(`/api/tasks/${encodeURIComponent(id)}/status`,{status:'in_progress',note,expected_execution_version:version}),'工序已开始');}
  const op=a.replace('task-exec-','');let body='',label='保存';
  if(op==='progress'){body=executionCountInput(t,true)+`<label class="field">进度说明<textarea name="note" required maxlength="2000" placeholder="例如：左侧板已完成3件，剩余7件">${esc(note)}</textarea></label>`;label='保存累计进度';}
  if(op==='pause'||op==='switch'){body=`<label class="field">暂停分类<select name="reason" required>${Object.entries(executionPauseNames).map(([v,n])=>`<option value="${v}" ${v===(op==='switch'?'urgent':'material')?'selected':''}>${n}</option>`).join('')}</select></label>`+executionCountInput(t)+`<label class="field">暂停原因<textarea name="note" required maxlength="1000" placeholder="说明缺什么材料、哪里异常，或哪张急单需要先做">${esc(note)}</textarea></label><label class="field">交接说明<textarea name="handover_note" required maxlength="2000" placeholder="做到哪一步、半成品放在哪里、恢复时接着做什么">${esc(t.handover_note||'')}</textarea></label>`;label=op==='switch'?'保存交接并切换':'保存暂停与交接';}
  if(op==='resume'){body=`${executionHandover(t)}<label class="field">解除暂停依据<textarea name="note" required maxlength="2000" placeholder="例如：缺料已补齐并核对批次；急单已结束，可继续原任务"></textarea></label><label class="field">补充交接说明<textarea name="handover_note" maxlength="2000">${esc(t.handover_note||'')}</textarea></label>`;label='恢复并继续原任务';}
  if(op==='priority'){body=`<label class="field">任务优先级<select name="priority">${executionPriorityNames.map((n,i)=>`<option value="${i}" ${executionPriority(t)===i?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">调整依据<textarea name="reason" required maxlength="1000" placeholder="例如：门店今晚安装，优先处理本任务"></textarea></label><p class="execution-caption">需要立即换单，请使用“暂停并换做”。</p>`;label='保存优先级';}
  if(op==='complete'){body=`<div class="execution-blockers"><strong>将明确确认整项工序已完成</strong><p>尚未全部做完，请返回记录部分进度。</p></div><label class="field">完工 / 检验记录<textarea name="note" ${(t.trade||t.role)==='质检'||(t.process||'').includes('electrical')?'required':''} placeholder="填写验收结果与本次完工说明">${esc(note)}</textarea></label><label class="execution-confirm"><input name="confirm" type="checkbox" required> 全部数量已完成，并通过本工序验收</label>`;label='确认整项完工';}
  if(op==='switch'){
    const person=executionPerson(t);if(!person)throw new Error('先分配负责人，再选择换做任务');
    const queued=await executionLoadQueue({person_id:person.id,from_task_id:id}),targets=executionSorted(queued.filter(x=>x.id!==id&&['ready','blocked'].includes(x.status)));
    body+=`<label class="field">换做任务（${esc(person.name)} · 跨项目）<select id="switch-target" name="target_task_id" required><option value="">请选择另一项任务</option>${targets.map(x=>`<option value="${esc(x.id)}" ${x.can_switch?'':'disabled'}>${executionPriorityNames[executionPriority(x)]} · ${esc(state.projects.find(p=>p.id===x.project_id)?.name||'项目')} · ${esc(x.title||x.name)}${x.can_switch?'':' · 条件未满足'}</option>`).join('')}</select></label><input type="hidden" id="switch-target-version" name="target_version"><div id="switch-target-preview" class="execution-target"><p>选择同一负责人的另一项工序，查看前置条件。</p></div><label class="field" id="switch-resolution" hidden>目标任务解除暂停依据<textarea name="target_note" maxlength="2000" placeholder="说明为什么现在可以恢复目标任务"></textarea></label>${!targets.some(x=>x.can_switch)?'<p class="execution-caption">当前没有满足切换条件的任务。可以先保存原任务暂停，再处理其他任务的前置条件。</p>':''}<details class="execution-engineering"><summary>查看不可切换的任务与原因</summary>${targets.filter(x=>!x.can_switch).map(x=>`<p><strong>${esc(x.title||x.name)}</strong><br>${(x.switch_blockers||['条件未满足']).map(esc).join('；')}</p>`).join('')||'<p>当前队列中的候选均满足切换条件。</p>'}</details>`;
  }
  executionOperationForm(t,op,body,button(label,'task-exec-save',op==='switch'?'arrow':'check','primary',`data-operation="${op}" data-id="${esc(id)}"`));
}
function documentsModal(){openModal('工程来源文件',`${docs().length?docs().map(d=>`<div style="padding:14px 0;border-bottom:1px solid var(--line)"><div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><strong style="font-size:12px">${esc(d.filename)}</strong>${d.purpose==='process'?tag(processBasisIsCurrent(d)?'resolved':'review',processBasisIsCurrent(d)?'工艺依据已核验':'待工作包核验'):tag(d.status)}<a href="/api/documents/${encodeURIComponent(d.id)}/download" style="font-size:11px;margin-left:auto">原文件</a></div><p class="mono muted" style="font-size:9px;overflow-wrap:anywhere;margin:8px 0">SHA256 ${esc(d.sha256)}</p>${d.warnings?.map(w=>`<p class="muted" style="font-size:11px">${esc(w)}</p>`).join('')||''}${uploadDocIsPdf(d)?button('查看图纸','preview-upload','expand','',`data-id="${esc(d.id)}"`):''}${uploadModelLink(d)}${globalThis.KanpaceIntelligence?.engineeringButtons(d)||''}${d.geometry?.length?button('查看实体几何','view-doc',null,'',`data-id="${esc(d.id)}"`):''}${!d.superseded&&(d.purpose==='process'||(['needs_conversion','error'].includes(d.status)||d.part_count===0)&&!d.resolved)?button(d.purpose==='process'?'绑定工作包核验':'登记补充依据','resolve-doc',null,'',`data-id="${esc(d.id)}"`):''}</div>`).join(''):empty('暂无来源文件','导入后可查看原件与解析记录',null)}`,button('关闭','close'));}
let processBasisDialog=null;
async function processBasisModal(id){
  processBasisDialog=null;
  const project=currentProject(),documentRecord=state.documents.find(d=>d.id===id&&d.project_id===project?.id&&d.purpose==='process');
  if(!documentRecord||!project)return;
  if(typeof ensureOperationsLoaded==='function')await ensureOperationsLoaded(true);
  if(currentProject()?.id!==project.id)return;
  const workflow=typeof operationsData!=='undefined'?(operationsData?.workflows||[]).find(w=>w.id===project.workflow_id&&w.project_id===project.id):null;
  const linked=workflow?.objects?.filter(object=>Array.isArray(object.document_ids)&&object.document_ids.includes(id))||[];
  const ready=workflow?.status==='reviewed'&&workflow.revision===project.revision&&linked.length;
  if(!ready){
    openModal('先核对项目工作包',`<p>${esc(documentRecord.filename)}</p><p>${!workflow?'先按本厂流程创建工作包，并为工作对象选择这份工艺资料。':!linked.length?'请在工作包中把这份工艺资料关联到对应工作对象，再完成工作包复核。':'请先复核当前工程版本的工作包，再确认工艺资料与任务的对应关系。'}</p>`,button('关闭','close')+`<a class="btn primary" href="#page=templates&tab=parts&project=${encodeURIComponent(project.id)}" data-action="close">打开项目工作包</a>`);
    return;
  }
  processBasisDialog={document_id:id,project_id:project.id,workflow_id:workflow.id,expected_workflow_version:workflow.version,expected_revision:project.revision};
  openModal('核验工艺资料与工作包',`<p><strong>${esc(documentRecord.filename)}</strong></p><p>对应对象：${linked.map(o=>esc(o.code+' · '+o.name)).join('；')}</p><form id="resolve-form" data-purpose="process"><label class="field">核验记录<textarea name="note" required maxlength="2000" placeholder="记录工艺资料版次、适用对象、数量及工序核对结果"></textarea></label><label class="ops-check"><input name="acknowledge_process_basis" type="checkbox" required>已打开原件，核对其内容与当前工作包一致</label></form>`,button('取消','close')+button('确认核验','do-resolve','check','primary',`data-id="${esc(id)}"`));
}
async function saveProcessBasis(buttonEl){
  const form=$('#resolve-form'),snapshot=processBasisDialog;
  if(!snapshot||snapshot.document_id!==buttonEl.dataset.id||!form?.reportValidity())return;
  const note=formValues('#resolve-form').note;
  return submitOperation(buttonEl,()=>api(`/api/documents/${encodeURIComponent(snapshot.document_id)}/resolve`,{note,workflow_id:snapshot.workflow_id,expected_workflow_version:snapshot.expected_workflow_version,expected_revision:snapshot.expected_revision,acknowledge_process_basis:true}),'工艺依据已绑定当前工作包版本');
}
function capabilitiesModal(){openModal('本地版本 · 能力与依据',`<p>KANPACE面向木作、五金、玻璃与灯光综合展示柜，工艺按已确认的构件与本厂规则生成。</p><div class="capability"><strong>图纸与拆单</strong><span>CSV/JSON BOM、支持的 ASCII DXF；PDF 上传、翻页放大；已有订单按来源关联施工图与料单图片；构件复核、工种范围和工程版本追溯。</span></div><div class="capability"><strong>工程模型查看</strong><span>STEP / IGES / BREP / GLB / OBJ / STL；模型结构、旋转缩放、隔离、爆炸、剖切、近似测距，以及模型零件关联已有拆单。模型包围尺寸不作为生产下料尺寸。</span></div><div class="capability"><strong>生产排程</strong><span>人工日排程、工作周设置、物料齐套、人员有限容量、前后工序日期校验、改期与撤销记录、CSV导出。</span></div><div class="capability"><strong>生产执行</strong><span>工序依赖、技能与负载派工、部分进度、暂停交接、插单恢复；USB / Wi-Fi 工牌下发与回执；项目完成或发货后退出派工，保留历史。</span></div><div class="capability"><strong>SolidWorks</strong><span>附 Windows BOM 属性与 STEP 导出桥接，需本机安装 SolidWorks。该桥接尚未在 Windows 实机验证。</span></div><div class="capability"><strong>尚未实现</strong><span>原生 MAX / DWG / SolidWorks 在本机直接解析、任意扫描图自动生成可生产的拆单、参数化建模、钣金展开及通用企业系统连接器。OCR、CAD 几何分析、矩形套料与有限产能排程已有独立入口，结果仍需按工程依据复核。</span></div>`,button('关闭','close'));}
