function deviceWifiNetworkOptions(){return (deviceWifi?.networks||[]).map(n=>`<option value="${esc(n.ssid)}">${esc(n.ssid)} · ${num(n.rssi)} dBm${n.secure?' · 加密':' · 开放'}</option>`).join('');}
function deviceWifiStatus(){
  const w=deviceWifi,cached=w?.cached===true,active=w?.connected&&!cached,awaiting=w?.configured&&!w?.observed_at&&!w?.ip;
  const label=active?'已接入 Wi-Fi':awaiting?'正在连接 Wi-Fi':cached?'上次连接信息':w?.configured?'尚未连上 Wi-Fi':'尚未设置 Wi-Fi';
  const note=active?`${w.ssid||'已连接网络'}${deviceStatus?.transport==='wifi'?'':' · 可尝试切换无线连接'}`:awaiting?'稍后刷新连接状态。':cached?`${w.ssid||'网络'}${w.ip?' · '+w.ip:''} · 请刷新确认。`:w?.configured?'核对 2.4 GHz 网络名称和密码，再刷新状态。':'连接 USB 后，选择网络并保存。';
  return `<div class="device-wifi-status-box"><span class="badge ${active?'green':'amber'}">${icon('wifi')}${esc(label)}</span><p>${esc(note)}</p>${cached&&w?.observed_at?`<small>上次更新 ${esc(deviceTimestamp(w.observed_at))}</small>`:''}${w?.scan_pending?'<p>正在扫描，稍后再次点击查看结果。</p>':''}</div>`;
}
function syncDeviceWifiUI(){
  const setup=$('#device-wifi-settings');if(setup&&deviceWifi&&!setup.dataset.initialized){setup.open=!deviceWifi.configured;setup.dataset.initialized='true';}const ssid=$('#device-wifi-ssid');if(ssid&&!ssid.dataset.edited&&!ssid.value&&deviceWifi?.ssid)ssid.value=deviceWifi.ssid;
  const usb=$('#device-usb-controls'),wifi=$('#device-wifi-controls');if(usb)usb.hidden=deviceMethod!=='usb';if(wifi)wifi.hidden=deviceMethod!=='wifi';
  document.querySelectorAll('[data-action="device-mode"]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.mode===deviceMethod));b.tabIndex=b.dataset.mode===deviceMethod?0:-1;});
  const transport=$('#device-transport-label');if(transport)transport.textContent=deviceStatus?.transport==='wifi'?'Wi-Fi · 局域网':'USB · 本机';
  const status=$('#device-wifi-status');if(status)deviceReplaceContent(status,deviceWifiStatus());
  const options=$('#device-wifi-networks');if(options)options.innerHTML=deviceWifiNetworkOptions();
  const ip=$('#device-wifi-ip');if(ip)ip.textContent=deviceWifi?.ip||'待连接网络';
  const error=$('#device-wifi-error');if(error)error.textContent=deviceWifiError;
  const usbReady=deviceStatus?.state==='ready'&&deviceStatus?.transport!=='wifi', busy=deviceBusy||deviceWifiBusy;
  for(const action of ['scan','config']){const b=$(`[data-action="device-wifi-${action}"]`);if(b){b.disabled=busy||!usbReady;b.title=usbReady?'':'请先通过 USB 连接开发板并验证固件';}}
  const statusButton=$('[data-action="device-wifi-status"]');if(statusButton)statusButton.disabled=busy;
  const connect=$('[data-action="device-wifi-connect"]');if(connect){connect.disabled=busy||!deviceWifi?.ip||(deviceStatus?.state==='ready'&&deviceStatus?.transport==='wifi');connect.textContent=deviceStatus?.state==='ready'&&deviceStatus?.transport==='wifi'?'已切换 Wi-Fi 连接':'切换 Wi-Fi 连接';}
  const disconnect=$('#device-wifi-disconnect-button');if(disconnect)disconnect.disabled=busy||!deviceStatus||deviceStatus.state==='disconnected';
}
async function deviceWifiAction(action){
  if(deviceBusy||deviceWifiBusy)return;
  let data={},path='/api/device/wifi-status';
  if(action==='device-wifi-config'){
    const form=$('#device-wifi-form');if(!form.reportValidity())return;
    const password=$('#device-wifi-password');data={ssid:$('#device-wifi-ssid').value,password:password.value};password.value='';path='/api/device/wifi-config';
  }else if(action==='device-wifi-scan')path='/api/device/wifi-scan';
  else if(action==='device-wifi-connect'){if(!deviceWifi?.ip)throw new Error('尚未获取开发板 IP，请先通过 USB 配网并刷新无线状态');data={transport:'wifi',host:deviceWifi.ip};path='/api/device/connect';}
  deviceWifiBusy=true;deviceWifiError='';syncDeviceUI(false);
  try{
    const result=await deviceApi(path,action==='device-wifi-status'?undefined:data);
    if(result.device)deviceStatus=result.device;if(result.ports)devicePorts=result.ports;
    if(result.wifi)deviceWifi={...deviceWifi,...result.wifi};else if(result.device?.wifi)deviceWifi={...deviceWifi,...result.device.wifi};
    if(action==='device-wifi-config'){deviceWifi={...deviceWifi,configured:true,connected:false,cached:false,ip:''};toast('Wi-Fi 配置已提交，请刷新无线状态确认联网与 IP');}
    if(action==='device-wifi-scan')toast(deviceWifi?.scan_pending?'开发板正在扫描，稍后再次点击扫描读取结果':`扫描到 ${deviceWifi?.networks?.length||0} 个网络，可在 Wi-Fi 名称中选择`);
    if(action==='device-wifi-connect')toast(deviceStatus?.state==='ready'?'已通过无线固件握手，可通过 Wi-Fi 派发任务':'无线连接待确认，请核对设备状态');
  }catch(e){deviceWifiError=e.message;}
  finally{data=null;deviceWifiBusy=false;syncDeviceUI(false);ensureDevicePolling();}
}
